"""Independent reference planner used only for testing.

Enumerates ordered trees, encodings and resident sets directly from the
protocol text and keeps the (work, pages, cache) frontier small by exact
dominance filtering (a dominated triple can never help any combination).
"""
import sys
sys.path.insert(0, '/workspace/submission')
from solver import traffic, LANES, WIDTH

LIMIT = 3000


def compositions(n, b):
    if b == 1:
        yield (n,)
        return
    for first in range(1, n - b + 2):
        for rest in compositions(n - first, b - 1):
            yield (first,) + rest


def alloc(kind, b, span, mode):
    keys = (b - 1) if kind == 0 else span
    used = 32 + (4 * b if kind == 0 else 0) + keys * WIDTH[mode]
    return (used + 63) // 64 * 64


def pareto(triples):
    keep = []
    for t in sorted(triples):
        if any(k[0] <= t[0] and k[1] <= t[1] and k[2] <= t[2] and k != t for k in keep):
            continue
        keep = [k for k in keep
                if not (t[0] <= k[0] and t[1] <= k[1] and t[2] <= k[2] and t != k)]
        keep.append(t)
    return keep


def shrink(lst):
    lst = sorted(set(lst))
    if len(lst) > LIMIT:
        lst = pareto(lst)
    return lst


def version_options(R, starts, per_version, costs):
    hit, miss, dec = costs
    total, qpref, left, right = traffic(R, per_version)
    memo = {}

    def rec(i, j):
        key = (i, j)
        if key in memo:
            return memo[key]
        s = j - i
        spread = starts[j - 1] - starts[i]
        legal = [True, spread < (1 << 64), spread < (1 << 32)]
        T = total - left[i] - right[j]
        Q = qpref[j] - qpref[i]
        found = []
        if s <= 8:
            for m in range(3):
                if not legal[m]:
                    continue
                P = alloc(1, 0, s, m) // 64
                D = -(-s // LANES[m]) + dec[m]
                for cached in (0, 1):
                    w = P * (hit if cached else miss) * T + D * Q
                    found.append((w, P, P if cached else 0))
        for b in range(2, min(9, s) + 1):
            for m in range(3):
                if not legal[m]:
                    continue
                P = alloc(0, b, s, m) // 64
                D = (-(-(b - 1) // LANES[m])) + dec[m]
                for cached in (0, 1):
                    nw = P * (hit if cached else miss) * T + D * Q
                    for parts in compositions(s, b):
                        combined = [(0, 0, 0)]
                        pos = i
                        for p in parts:
                            child = rec(pos, pos + p)
                            pos += p
                            nxt = []
                            for a in combined:
                                for c in child:
                                    nxt.append((a[0] + c[0], a[1] + c[1], a[2] + c[2]))
                            combined = shrink(nxt)
                        for c in combined:
                            found.append((nw + c[0], P + c[1],
                                          (P if cached else 0) + c[2]))
        found = shrink(found)
        memo[key] = found
        return found

    opts = rec(0, R)
    hop_pages = (R * 4 + 63) // 64
    return [(w, p + 1 + hop_pages, c) for (w, p, c) in opts]


def brute_case(versions, per_version, costs, cache_pages):
    all_opts = [version_options(len(s), s, pv, costs)
                for (s, h), pv in zip(versions, per_version)]
    combined = [(0, 0, 0)]
    for opts in all_opts:
        nxt = []
        for a in combined:
            for c in opts:
                if a[2] + c[2] <= cache_pages:
                    nxt.append((a[0] + c[0], a[1] + c[1], a[2] + c[2]))
        combined = shrink(nxt)
    best = min((w, p) for (w, p, c) in combined)
    return list(best)
